def _pose():
    pose = mock.Mock()
    pose.X.return_value = 0.0
    pose.Y.return_value = 0.0
    pose.rotation.return_value.radians.return_value = 0.0
    return pose


class _Tracker:
    def __init__(self, name, calls):
        self.name = name
        self.calls = calls

    def update(self, detections, *_pose):
        self.calls.append((self.name, [obj.id for obj in detections]))
        return detections


class ObjectSourceTagTests(unittest.TestCase):
    def test_serialization_round_trips_source_camera_tags(self):
        obj = Object(
            0.0,
            0.0,
            0.0,
            name="fuel",
            source_cameras=["left", "right"],
        )
        self.assertEqual(obj.source_cameras, ["left", "right"])
        self.assertEqual(obj.source_camera, "left")
        data = obj.to_dict()
        self.assertEqual(data["source_cameras"], ["left", "right"])
        self.assertEqual(data["source_camera"], "left")
        restored = Object.from_dict(data)
        self.assertEqual(restored.source_cameras, ["left", "right"])
        self.assertEqual(restored.source_camera, "left")

    def test_single_source_is_kept_and_duplicates_are_removed(self):
        obj = Object(0.0, 0.0, source_cameras=["left", "left"], source_camera="right")
        self.assertEqual(obj.source_cameras, ["right", "left"])
        self.assertEqual(obj.source_camera, "right")


class CameraNameTests(unittest.TestCase):
    def test_camera_name_prefers_the_configured_lane_over_the_device_source(self):
        class Camera:
            _camera_config = {"name": "Left", "source": 4}

        self.assertEqual(iSpy._camera_name(Camera()), "Left")
        self.assertEqual(iSpy._camera_label(Camera(), 0), "Left")
        self.assertEqual(MultipleCameraHandler._camera_name(Camera(), 0), "Left")

    def test_camera_name_fallback_is_indexed(self):
        class Camera:
            pass

        self.assertEqual(iSpy._camera_name(Camera(), 2), "Camera 3")
        self.assertEqual(MultipleCameraHandler._camera_name(Camera(), 1), "Camera 2")

    def test_dict_backed_camera_config_still_works(self):
        class Camera:
            config = {"name": "Front"}

        self.assertEqual(iSpy._camera_name(Camera()), "Front")
        self.assertEqual(MultipleCameraHandler._camera_name(Camera(), 0), "Front")


class TriangulationSourceTests(unittest.TestCase):
    def test_merged_detection_keeps_every_contributing_camera(self):
        handler = MultipleCameraHandler([], {"unit": "frc"})
        left = Object(
            0.0,
            0.0,
            name="fuel",
            ray_origin=np.zeros(3),
            ray_direction=np.ones(3),
            source_cameras=["left"],
        )
        right = Object(
            0.0,
            0.0,
            name="fuel",
            ray_origin=np.zeros(3),
            ray_direction=np.ones(3),
            source_cameras=["right"],
        )
        with mock.patch(
            "iSpy.utilities.MultipleCameraHandler.triangulation.closest_point_between_rays",
            return_value=(np.zeros(3), 0.1),
        ):
            merged = handler._merge_with_triangulation([[left], [right]])
        try:
            self.assertEqual(len(merged), 1)
            self.assertEqual(merged[0].source_cameras, ["left", "right"])
            self.assertEqual(merged[0].source_camera, "left")
            self.assertEqual(merged[0].depth_source, "triangulated")
        finally:
            handler.destroy()


class LaneTrackerRuntimeTests(unittest.TestCase):
    def _vision(self, *, configs, camera_trackers, global_trackers=None):
        vision = iSpy.__new__(iSpy)
        vision.logger = mock.Mock()
        vision.trackers = global_trackers or {}
        vision.camera_trackers = camera_trackers
        vision._camera_tracker_configs = configs
        vision._addon_breakdown_parts = lambda _plugin: {}
        return vision

    def test_explicit_lanes_only_process_their_own_objects(self):
        calls = []
        vision = self._vision(
            configs={"left": ["left-tracker"], "right": ["right-tracker"]},
            camera_trackers={
                "left": {"left-tracker": _Tracker("left", calls)},
                "right": {"right-tracker": _Tracker("right", calls)},
            },
            global_trackers={"global": _Tracker("global", calls)},
        )
        left = Object(0, 0, source_cameras=["left"])
        right = Object(0, 0, source_cameras=["right"])
        merged = Object(0, 0, source_cameras=["left", "right"])

        result = vision._run_lane_trackers(
            [left, right, merged], _pose(), {}
        )

        self.assertEqual([obj.id for obj in result], [left.id, merged.id, right.id])
        self.assertEqual(
            calls,
            [
                ("left", [left.id, merged.id]),
                ("right", [right.id, merged.id]),
            ],
        )
        self.assertEqual(merged.source_camera, "left")
        self.assertEqual(merged.source_cameras, ["left", "right"])

    def test_lane_with_no_trackers_does_not_fall_back_to_global_trackers(self):
        calls = []
        vision = self._vision(
            configs={"left": []},
            camera_trackers={"left": {}},
            global_trackers={"global": _Tracker("global", calls)},
        )
        left = Object(0, 0, source_cameras=["left"])
        right = Object(0, 0, source_cameras=["right"])

        result = vision._run_lane_trackers([left, right], _pose(), {})

        # An explicit empty lane is still a lane: its detections bypass the
        # legacy global trackers.  Only cameras without lane configuration
        # keep using the global tracker list.
        self.assertEqual([obj.id for obj in result], [left.id, right.id])
        self.assertEqual(calls, [("global", [right.id])])

    def test_no_per_camera_configuration_keeps_the_global_tracker_path(self):
        calls = []
        vision = self._vision(
            configs={},
            camera_trackers={},
            global_trackers={"global": _Tracker("global", calls)},
        )
        objects = [
            Object(0, 0, source_cameras=["left"]),
            Object(0, 0, source_cameras=["right"]),
        ]

        result = vision._run_lane_trackers(objects, _pose(), {})

        self.assertEqual([obj.id for obj in result], [obj.id for obj in objects])
        self.assertEqual(calls, [("global", [obj.id for obj in objects])])

    def test_solo_loop_uses_the_camera_lane_tracker(self):
        calls = []
        vision = self._vision(
            configs={"left": ["left-tracker"]},
            camera_trackers={"left": {"left-tracker": _Tracker("left", calls)}},
            global_trackers={"global": _Tracker("global", calls)},
        )
        obj = Object(0, 0, source_cameras=[])

        class Camera:
            _camera_config = {"name": "left"}
            plugin_name = "hsv_detection"

            def get_frame_age(self):
                return 0.0

            def get_code_times(self):
                return {}

            def in_calibration_mode(self):
                return False

        vision.cameras = []
        vision._raw_frames = lambda _cameras: {}
        vision._reset_frame_processor_times = lambda: None
        vision.run_solo_vision = lambda _camera: (
            [obj],
            np.zeros((4, 4, 3), dtype=np.uint8),
        )
        vision._merge_frame_processor_times = lambda _times: 0.0
        vision._get_pose = lambda _times=None: _pose()
        vision._annotations_wanted = lambda: False

        result = vision._run_loop_body_solo(Camera())

        self.assertEqual(calls, [("left", [obj.id])])
        self.assertEqual(result["detections"][0].source_cameras, ["left"])
        self.assertNotIn("global", {name for name, _ids in calls})

    def test_tracker_items_respect_an_explicit_empty_lane(self):
        vision = self._vision(
            configs={"left": []},
            camera_trackers={"left": {}},
            global_trackers={"global": _Tracker("global", [])},
        )
        explicit, items = vision._tracker_items_for_camera("left")
        self.assertTrue(explicit)
        self.assertEqual(items, [])
        explicit, items = vision._tracker_items_for_camera("other")
        self.assertFalse(explicit)
        self.assertEqual([name for name, _plugin in items], ["global"])


class UtilityFilteringRuntimeTests(unittest.TestCase):
    def _vision(self, utility_sources):
        vision = iSpy.__new__(iSpy)
        vision.logger = mock.Mock()
        vision.config = {"utility_sources": utility_sources}
        vision._addon_breakdown_parts = lambda _plugin: {}
        return vision

    def test_missing_key_keeps_legacy_all_camera_behavior(self):
        vision = self._vision({})
        payload = {"detections": [Object(0, 0, source_cameras=["left"])]}
        self.assertIs(vision._utility_frame_data(payload, "target_selector"), payload)

    def test_malformed_source_list_keeps_legacy_behavior(self):
        vision = self._vision({"target_selector": "left"})
        payload = {"detections": [Object(0, 0, source_cameras=["left"])]}
        self.assertIs(vision._utility_frame_data(payload, "target_selector"), payload)

    def test_explicit_sources_filter_detections_and_update_counts(self):
        vision = self._vision({"target_selector": ["left"]})
        left = Object(0, 0, source_cameras=["left"])
        right = Object(0, 0, source_cameras=["right"])
        merged = Object(0, 0, source_cameras=["left", "right"])
        payload = {
            "detections": [left, right, merged],
            "detection_count": 3,
            "frame": "kept",
        }

        scoped = vision._utility_frame_data(payload, "target_selector")

        self.assertEqual([obj.id for obj in scoped["detections"]], [left.id, merged.id])
        self.assertEqual(scoped["detection_count"], 2)
        self.assertEqual(scoped["utility_sources"], ["left"])
        self.assertEqual(scoped["frame"], "kept")
        self.assertEqual(len(payload["detections"]), 3)

    def test_explicit_empty_sources_produce_no_detections(self):
        vision = self._vision({"target_selector": []})
        payload = {"detections": [Object(0, 0, source_cameras=["left"])]}
        scoped = vision._utility_frame_data(payload, "target_selector")
        self.assertEqual(scoped["detections"], [])
        self.assertEqual(scoped["detection_count"], 0)

    def test_objects_without_source_tags_only_match_all_camera_mode(self):
        vision = self._vision({"target_selector": ["left"]})
        untagged = Object(0, 0)
        payload = {"detections": [untagged], "detection_count": 1}
        scoped = vision._utility_frame_data(payload, "target_selector")
        self.assertEqual(scoped["detections"], [])

    def test_update_utilities_filters_configured_utilities_and_keeps_rollback_full(self):
        vision = self._vision(
            {
                "target_selector": ["left"],
                "empty_utility": [],
            }
        )
        seen = {}

        class Utility:
            def __init__(self, name):
                self.name = name

            def update(self, frame_data):
                seen[self.name] = frame_data

        vision.utilities = {
            "target_selector": Utility("target_selector"),
            "empty_utility": Utility("empty_utility"),
            "unconfigured": Utility("unconfigured"),
            "rollback": Utility("rollback"),
        }
        left = Object(0, 0, source_cameras=["left"])
        right = Object(0, 0, source_cameras=["right"])
        frame = {
            "detections": [left, right],
            "detection_count": 2,
            "code_times": {},
        }

        vision._update_utilities(frame)

        self.assertEqual(
            [obj.id for obj in seen["target_selector"]["detections"]], [left.id]
        )
        self.assertEqual(seen["empty_utility"]["detections"], [])
        self.assertEqual(
            [obj.id for obj in seen["unconfigured"]["detections"]],
            [left.id, right.id],
        )
        self.assertEqual(
            [obj.id for obj in seen["rollback"]["detections"]], [left.id, right.id]
        )
        self.assertEqual(seen["rollback"]["detection_count"], 2)
        self.assertEqual(len(frame["detections"]), 2)


class LaneConfigLoadingTests(unittest.TestCase):
    def _config(self, trackers):
        cfg = iSpyConfig()
        cfg.config["app_mode"] = False
        cfg.config["camera_configs"] = {
            "left": {"name": "left", "source": 0, "trackers": ["example/example_tracker"]},
            "right": {"name": "right", "source": 1, "trackers": []},
            "legacy": {"name": "legacy", "source": 2},
        }
        cfg.config["plugins"] = {
            "trackers": trackers,
            "utilities": {},
            "frame_processors": {},
        }
        data_dir = tempfile.mkdtemp(prefix="ispy_lane_runtime_")
        self.addCleanup(shutil.rmtree, data_dir, True)
        cfg.config["rollback"] = {"data_dir": data_dir}
        return cfg

    def test_constructor_builds_instances_only_for_explicit_lane_configs(self):
        cfg = self._config({"example/example_tracker": {"count_start": 3}})
        vision = iSpy(cameras=[], config=cfg)
        try:
            self.assertEqual(
                set(vision.camera_trackers), {"left", "right"}
            )
            self.assertEqual(
                set(vision.camera_trackers["left"]), {"example/example_tracker"}
            )
            self.assertEqual(vision.camera_trackers["right"], {})
            self.assertNotIn("legacy", vision.camera_trackers)
            self.assertEqual(vision._camera_tracker_configs["left"], ["example/example_tracker"])
            self.assertEqual(vision._camera_tracker_configs["right"], [])
            tracker = vision.camera_trackers["left"]["example/example_tracker"]
            self.assertEqual(tracker.count, 3)
        finally:
            vision._stop_all_plugins()

    def test_disabled_tracker_is_not_instantiated_for_a_lane(self):
        cfg = self._config({})
        vision = iSpy(cameras=[], config=cfg)
        try:
            self.assertNotIn("example/example_tracker", vision.trackers)
            self.assertEqual(vision.camera_trackers["left"], {})
            self.assertEqual(
                vision._camera_tracker_configs["left"], ["example/example_tracker"]
            )
        finally:
            vision._stop_all_plugins()


if __name__ == "__main__":
    unittest.main()
